 func (dm *DVEManager) GetNodes(filter *NodeFilter) ([]*objects.DVENode, error) {
 	dm.mu.RLock()
 	defer dm.mu.RUnlock()

 	var nodes []*objects.DVENode

 	err := dm.db.GetObjectsByPrefix("dve:nodes:", func(key string, value []byte) bool {
